BEGIN;
CREATE TABLE public.external_contributors(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),preferred_name text NOT NULL,sort_name text,entity_type text NOT NULL DEFAULT 'person',country_code text,country text,date_of_birth date,date_of_death date,birth_place text,occupations text[] NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'draft',has_image boolean NOT NULL DEFAULT false,image_updated_at timestamptz,editorial_notes text,metadata jsonb NOT NULL DEFAULT '{}',created_by uuid REFERENCES auth.users(id) ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
 CONSTRAINT external_contributors_name_nonempty CHECK(btrim(preferred_name)<>''),CONSTRAINT external_contributors_entity_type CHECK(entity_type IN('person','group','organization')),CONSTRAINT external_contributors_country_code CHECK(country_code IS NULL OR country_code~'^[A-Z]{2}$'),CONSTRAINT external_contributors_status CHECK(status IN('draft','verified','disputed','archived')),CONSTRAINT external_contributors_dates CHECK(date_of_death IS NULL OR date_of_birth IS NULL OR date_of_death>=date_of_birth),CONSTRAINT external_contributors_metadata CHECK(jsonb_typeof(metadata)='object'));
CREATE INDEX external_contributors_name_idx ON public.external_contributors(lower(preferred_name));CREATE INDEX external_contributors_country_idx ON public.external_contributors(country_code,status);
CREATE TABLE public.editorial_assertion_external_contributors(assertion_id uuid PRIMARY KEY REFERENCES public.editorial_assertions(id) ON DELETE CASCADE,external_contributor_id uuid NOT NULL REFERENCES public.external_contributors(id) ON DELETE RESTRICT);
ALTER TABLE public.work_credits ALTER COLUMN artist_id DROP NOT NULL;ALTER TABLE public.work_credits ADD COLUMN external_contributor_id uuid REFERENCES public.external_contributors(id) ON DELETE RESTRICT;ALTER TABLE public.work_credits ADD CONSTRAINT work_credits_exactly_one_contributor CHECK(num_nonnulls(artist_id,external_contributor_id)=1);CREATE UNIQUE INDEX work_credits_external_role_uidx ON public.work_credits(work_id,external_contributor_id,role_id) WHERE external_contributor_id IS NOT NULL AND role_id IS NOT NULL;
ALTER TABLE public.recording_credits ADD COLUMN external_contributor_id uuid REFERENCES public.external_contributors(id) ON DELETE RESTRICT;ALTER TABLE public.recording_credits ADD CONSTRAINT recording_credits_exactly_one_contributor CHECK(num_nonnulls(artist_id,external_contributor_id)=1) NOT VALID;ALTER TABLE public.recording_credits VALIDATE CONSTRAINT recording_credits_exactly_one_contributor;CREATE INDEX recording_credits_external_idx ON public.recording_credits(external_contributor_id);
INSERT INTO public.editorial_capabilities(capability,description) VALUES('external_contributor.create','Create governed external contributor identities'),('external_contributor.edit','Edit governed external contributor identities') ON CONFLICT DO NOTHING;INSERT INTO public.editorial_role_capabilities(role,capability) SELECT role,capability FROM (VALUES('owner','external_contributor.create'),('owner','external_contributor.edit'),('admin','external_contributor.create'),('admin','external_contributor.edit'),('editor','external_contributor.create'),('editor','external_contributor.edit'))v(role,capability) ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION public.validate_assertion_subject() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$DECLARE n integer;BEGIN SELECT (SELECT count(*) FROM public.editorial_assertion_works WHERE assertion_id=NEW.id)+(SELECT count(*) FROM public.editorial_assertion_recordings WHERE assertion_id=NEW.id)+(SELECT count(*) FROM public.editorial_assertion_work_credits WHERE assertion_id=NEW.id)+(SELECT count(*) FROM public.editorial_assertion_recording_credits WHERE assertion_id=NEW.id)+(SELECT count(*) FROM public.editorial_assertion_isrcs WHERE assertion_id=NEW.id)+(SELECT count(*) FROM public.editorial_assertion_recording_work_targets WHERE assertion_id=NEW.id)+(SELECT count(*) FROM public.editorial_assertion_external_contributors WHERE assertion_id=NEW.id) INTO n;IF n<>1 THEN RAISE EXCEPTION 'assertion % must have exactly one typed subject/target (found %)',NEW.id,n;END IF;RETURN NEW;END$$;
CREATE OR REPLACE FUNCTION public.create_external_contributor(actor uuid,key uuid,name_value text,country_code_value text DEFAULT NULL,country_value text DEFAULT NULL,entity_type_value text DEFAULT 'person',source_ids uuid[] DEFAULT ARRAY[]::uuid[],notes_value text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE cached jsonb;contributor_uuid uuid;assertion_uuid uuid;decision_uuid uuid;source_uuid uuid;result_value jsonb;duplicates jsonb;BEGIN PERFORM public.require_editorial_capability(actor,'external_contributor.create');PERFORM pg_advisory_xact_lock(hashtextextended(actor::text||key::text,0));cached:=public.editorial_idempotent_result(actor,'external_contributor.create',key);IF cached IS NOT NULL THEN RETURN cached;END IF;IF btrim(coalesce(name_value,''))='' THEN RAISE EXCEPTION 'preferred name required';END IF;SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'preferred_name',preferred_name,'country_code',country_code)),'[]') INTO duplicates FROM public.external_contributors WHERE lower(regexp_replace(preferred_name,'[^[:alnum:]]','','g'))=lower(regexp_replace(btrim(name_value),'[^[:alnum:]]','','g'));
INSERT INTO public.external_contributors(preferred_name,sort_name,entity_type,country_code,country,editorial_notes,created_by)VALUES(btrim(name_value),btrim(name_value),entity_type_value,nullif(upper(btrim(country_code_value)),''),nullif(btrim(country_value),''),nullif(btrim(notes_value),''),actor)RETURNING id INTO contributor_uuid;
INSERT INTO public.editorial_assertions(assertion_type,predicate,asserted_value,verification_status,canonical_status,internal_notes,created_by,reviewed_by,reviewed_at)VALUES('external_contributor_identity','external_contributor.exists',jsonb_build_object('external_contributor_id',contributor_uuid,'preferred_name',btrim(name_value),'country_code',country_code_value),'verified','accepted',notes_value,actor,actor,now())RETURNING id INTO assertion_uuid;INSERT INTO public.editorial_assertion_external_contributors VALUES(assertion_uuid,contributor_uuid);FOREACH source_uuid IN ARRAY coalesce(source_ids,ARRAY[]::uuid[]) LOOP INSERT INTO public.editorial_assertion_evidence(assertion_id,source_id,relationship,created_by)VALUES(assertion_uuid,source_uuid,'supports',actor)ON CONFLICT DO NOTHING;END LOOP;
INSERT INTO public.editorial_decisions(decision_type,status,reason,requested_by,decided_by,resulting_canonical_state,decided_at)VALUES('create_external_contributor','executed','Create external contributor identity',actor,actor,jsonb_build_object('external_contributor_id',contributor_uuid),now())RETURNING id INTO decision_uuid;INSERT INTO public.editorial_decision_assertions VALUES(decision_uuid,assertion_uuid,'accepted');INSERT INTO public.editorial_audit_events(event_type,actor_type,actor_user_id,decision_id,table_name,row_id,after_state,reason)VALUES('external_contributor.created','human_editor',actor,decision_uuid,'external_contributors',contributor_uuid,jsonb_build_object('preferred_name',btrim(name_value),'country_code',country_code_value),'Governed external contributor creation');result_value:=jsonb_build_object('external_contributor_id',contributor_uuid,'assertion_id',assertion_uuid,'decision_id',decision_uuid,'possible_duplicates',duplicates);INSERT INTO public.editorial_idempotency_keys VALUES(actor,'external_contributor.create',key,result_value,now());RETURN result_value;END$$;
CREATE OR REPLACE FUNCTION public.create_external_work_credit(actor uuid,key uuid,work_uuid uuid,external_uuid uuid,role_uuid uuid,credited_as_value text DEFAULT NULL,detail_value text DEFAULT NULL,sequence_value integer DEFAULT NULL,source_ids uuid[] DEFAULT ARRAY[]::uuid[],internal_notes_value text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE cached jsonb;credit_uuid uuid;assertion_uuid uuid;decision_uuid uuid;role_code text;source_uuid uuid;result_value jsonb;BEGIN PERFORM public.require_editorial_capability(actor,'credit.create');PERFORM pg_advisory_xact_lock(hashtextextended(actor::text||key::text,0));cached:=public.editorial_idempotent_result(actor,'external_work_credit.create',key);IF cached IS NOT NULL THEN RETURN cached;END IF;SELECT r.code INTO role_code FROM public.credit_roles r JOIN public.credit_role_scopes s ON s.role_id=r.id AND s.scope='work' WHERE r.id=role_uuid AND r.status='active';IF NOT FOUND THEN RAISE EXCEPTION 'role not allowed at Work scope';END IF;PERFORM 1 FROM public.external_contributors WHERE id=external_uuid AND status<>'archived';IF NOT FOUND THEN RAISE EXCEPTION 'external contributor unavailable';END IF;PERFORM set_config('app.governed_credit','on',true);INSERT INTO public.work_credits(work_id,artist_id,external_contributor_id,role,role_id,credited_as,credit_detail,sequence,verification_status,notes)VALUES(work_uuid,NULL,external_uuid,role_code,role_uuid,nullif(btrim(credited_as_value),''),nullif(btrim(detail_value),''),sequence_value,'unverified',internal_notes_value)RETURNING id INTO credit_uuid;PERFORM set_config('app.governed_credit','off',true);INSERT INTO public.editorial_assertions(assertion_type,predicate,asserted_value,verification_status,canonical_status,internal_notes,created_by)VALUES('work_credit','work.credit',jsonb_build_object('work_credit_id',credit_uuid,'work_id',work_uuid,'external_contributor_id',external_uuid,'role_id',role_uuid,'credited_as',credited_as_value),'unverified','unresolved',internal_notes_value,actor)RETURNING id INTO assertion_uuid;INSERT INTO public.editorial_assertion_work_credits VALUES(assertion_uuid,credit_uuid);FOREACH source_uuid IN ARRAY coalesce(source_ids,ARRAY[]::uuid[]) LOOP INSERT INTO public.editorial_assertion_evidence VALUES(assertion_uuid,source_uuid,'supports',NULL,NULL,actor,now())ON CONFLICT DO NOTHING;END LOOP;INSERT INTO public.editorial_decisions(decision_type,status,reason,requested_by,decided_by,resulting_canonical_state,decided_at)VALUES('create_unverified_work_credit','executed','Create external-contributor Work credit',actor,actor,jsonb_build_object('work_credit_id',credit_uuid),now())RETURNING id INTO decision_uuid;INSERT INTO public.editorial_decision_assertions VALUES(decision_uuid,assertion_uuid,'considered');result_value:=jsonb_build_object('work_credit_id',credit_uuid,'assertion_id',assertion_uuid,'decision_id',decision_uuid);INSERT INTO public.editorial_idempotency_keys VALUES(actor,'external_work_credit.create',key,result_value,now());RETURN result_value;END$$;
CREATE OR REPLACE FUNCTION public.get_external_contributor_public(contributor_uuid uuid) RETURNS TABLE(id uuid,display_name text,country text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$SELECT e.id,e.preferred_name,coalesce(e.country,e.country_code) FROM public.external_contributors e WHERE e.id=contributor_uuid AND e.status IN('draft','verified')$$;
CREATE OR REPLACE FUNCTION public.get_public_recording_credits(recording_uuid uuid) RETURNS TABLE(role text,identity_type text,identity_id uuid,display_name text,artist_slug text,country text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT rc.role,'artist'::text,a.id,coalesce(nullif(rc.credited_as,''),a.name),a.slug,NULL::text
 FROM public.recording_credits rc JOIN public.artists a ON a.id=rc.artist_id
 WHERE rc.recording_id=recording_uuid AND a.status='published'
 UNION ALL
 SELECT rc.role,'external_contributor'::text,e.id,coalesce(nullif(rc.credited_as,''),e.preferred_name),NULL::text,coalesce(e.country,e.country_code)
 FROM public.recording_credits rc JOIN public.external_contributors e ON e.id=rc.external_contributor_id
 WHERE rc.recording_id=recording_uuid AND e.status IN('draft','verified')
$$;
ALTER TABLE public.external_contributors ENABLE ROW LEVEL SECURITY;ALTER TABLE public.editorial_assertion_external_contributors ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.external_contributors,public.editorial_assertion_external_contributors FROM PUBLIC,anon,authenticated;GRANT ALL ON public.external_contributors,public.editorial_assertion_external_contributors TO service_role;REVOKE ALL ON FUNCTION public.create_external_contributor(uuid,uuid,text,text,text,text,uuid[],text),public.create_external_work_credit(uuid,uuid,uuid,uuid,uuid,text,text,integer,uuid[],text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.create_external_contributor(uuid,uuid,text,text,text,text,uuid[],text),public.create_external_work_credit(uuid,uuid,uuid,uuid,uuid,text,text,integer,uuid[],text) TO service_role;REVOKE ALL ON FUNCTION public.get_external_contributor_public(uuid),public.get_public_recording_credits(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.get_external_contributor_public(uuid),public.get_public_recording_credits(uuid) TO anon,authenticated,service_role;
COMMENT ON TABLE public.external_contributors IS 'Canonical internal identities for non-Dominican participants in Dominican music; never public Artist catalog members.';NOTIFY pgrst,'reload schema';COMMIT;
